export function createDriving({traffic,railways,world,camera,keys,status}){
 let vehicle=null,snapCamera=true,accumulator=0,firstPerson=false,lookYaw=0,lookPitch=0;const originalNear=camera.near,originalFov=camera.fov;
 const lastPhysics={position:new T.Vector3(),yaw:0},chase={yaw:0,y:0,lift:0},lastChase={yaw:0,y:0,lift:0};
 const chaseDistance=()=>vehicle.path?23:Math.max(9,(vehicle.model?.length||4)*1.5),chaseHeight=()=>vehicle.path?8:Math.max(4.5,(vehicle.model?.height||1.4)+2.5);
 // The chase camera eases toward the vehicle in fixed steps, so heading changes swing gently, suspension bumps are filtered and hillsides behind the car lift it clear, without frame-rate dependent lag.
 function snapChase(yaw,y){chase.yaw=yaw;chase.y=y;chase.lift=0;Object.assign(lastChase,chase);snapCamera=false}
 function followChase(yaw,p,dt){Object.assign(lastChase,chase);chase.yaw+=Math.atan2(Math.sin(yaw-chase.yaw),Math.cos(yaw-chase.yaw))*(1-Math.exp(-dt*5));chase.y=T.MathUtils.clamp(chase.y+(p.y-chase.y)*(1-Math.exp(-dt*9)),p.y-1.5,p.y+1.5);const d=chaseDistance(),h=chaseHeight(),ground=world.tunnels?.at?.(p.x,p.z,p.y)?-Infinity:world.walkHeight(p.x+Math.sin(chase.yaw)*d,p.z+Math.cos(chase.yaw)*d,chase.y+h),need=Math.max(0,ground+1.3-chase.y-h);chase.lift+=(need-chase.lift)*(1-Math.exp(-dt*(need>chase.lift?18:3)))}
 
 function exit(){if(!vehicle)return;const leaving=vehicle;leaving.cockpitView=false;camera.near=originalNear;camera.fov=originalFov;camera.updateProjectionMatrix();leaving.controlled=false;delete leaving.renderPosition;delete leaving.renderYaw;if(leaving.path){leaving.wait=4;leaving.speed=0}else{leaving.parked=true;leaving.speed=0;if(!leaving.inWater&&!leaving.airborne)leaving.velocity=0;leaving.manualPark=true;leaving.braking=false;leaving.indicator=null}
  const water=!leaving.path&&world.water?.at(leaving.position.x,leaving.position.z);if(water&&!world.water.supported(leaving.position.x,leaving.position.z,leaving.position.y+2)){let x=leaving.position.x+Math.cos(leaving.yaw)*((leaving.model?.width||1.8)/2+.6),z=leaving.position.z-Math.sin(leaving.yaw)*((leaving.model?.width||1.8)/2+.6);if(!(world.freeSpace||world.free)(x,z,water.y)){x=leaving.position.x;z=leaving.position.z}const next=world.water.at(x,z);camera.position.set(x,next?Math.max(next.bed+.35,Math.min(next.y+.16,leaving.position.y+1.3)):world.walkHeight(x,z)+2,z)}else{const p=findLanding(world,camera.position.x,camera.position.z,{x:camera.position.x,z:camera.position.z});camera.position.set(p.x,world.walkHeight(p.x,p.z)+2,p.z)}vehicle=null;status.textContent='ON FOOT'}
 function recover(){if(!vehicle||vehicle.path||!vehicle.recovery)return false;Object.assign(vehicle.position,vehicle.recovery.position);vehicle.yaw=vehicle.recovery.yaw;vehicle.velocity=0;vehicle.verticalVelocity=0;vehicle.inWater=false;vehicle.airborne=false;vehicle.engineFlooded=false;vehicle.floodAge=0;vehicle.waterPitch=vehicle.waterRoll=0;vehicle.waterState='DRY';vehicle.indicator=null;vehicle.indicatorTurned=false;vehicle.parkHold=true;vehicle.steeringAngle=vehicle.yawRate=vehicle.slipAngle=vehicle.bodyPitch=vehicle.bodyRoll=0;vehicle.motionYaw=vehicle.yaw;vehicle.gear=1;vehicle.rpm=800;vehicle.renderPosition?.set(vehicle.position.x,vehicle.position.y,vehicle.position.z);vehicle.renderYaw=vehicle.yaw;lastPhysics.position.set(vehicle.position.x,vehicle.position.y,vehicle.position.z);lastPhysics.yaw=vehicle.yaw;accumulator=0;snapCamera=true;return true}

 function relocate(point){if(!vehicle||vehicle.path)return false;vehicle.recovery={position:{x:point.x,y:world.walkHeight(point.x,point.z),z:point.z},yaw:point.yaw};return recover()}
 function enter(kind){exit();vehicle=kind==='train'?railways.trains[0]:[...traffic.cars].filter(car=>kind==='car'||car.model?.id===kind).sort((a,b)=>Math.hypot(a.position.x-camera.position.x,a.position.z-camera.position.z)-Math.hypot(b.position.x-camera.position.x,b.position.z-camera.position.z))[0];if(!vehicle)return;snapCamera=true;accumulator=0;lastPhysics.position.set(vehicle.position?.x||0,vehicle.position?.y||0,vehicle.position?.z||0);lastPhysics.yaw=vehicle.yaw||0;if(!vehicle.path&&!vehicle.recovery)vehicle.recovery={position:{...vehicle.position},yaw:vehicle.yaw};vehicle.parkHold=true;vehicle.motionYaw=vehicle.yaw;vehicle.yawRate=vehicle.steeringAngle=0;vehicle.controlled=true;vehicle.cockpitView=firstPerson&&!vehicle.path;lookYaw=lookPitch=0;vehicle.speed=0;vehicle.velocity=0;vehicle.wait=0;return true}
 function toggleView(){if(!vehicle||vehicle.path)return false;firstPerson=!firstPerson;vehicle.cockpitView=firstPerson;snapCamera=true;lookYaw=lookPitch=0;return firstPerson}
 function look(dx,dy){if(!vehicle?.cockpitView)return false;lookYaw=T.MathUtils.clamp(lookYaw-dx*.0025,-1.3,1.3);lookPitch=T.MathUtils.clamp(lookPitch-dy*.0025,-.65,.6);return true}
 function update(dt){if(!vehicle)return false;let p,heading,speed,alpha=1;if(vehicle.path){const throttle=Number(!!(keys.w||keys.arrowup))-Number(!!(keys.s||keys.arrowdown));vehicle.speed=T.MathUtils.clamp(vehicle.speed+throttle*3*dt,0,28);if(keys[' '])vehicle.speed=Math.max(0,vehicle.speed-9*dt);if(keys.a||keys.arrowleft){vehicle.direction=1;vehicle.speed=0}if(keys.d||keys.arrowright){vehicle.direction=-1;vehicle.speed=0}const sample=vehicle.path.sample(vehicle.distance+vehicle.direction*10);p=sample.position;heading=Math.atan2(-sample.direction.x*vehicle.direction,-sample.direction.z*vehicle.direction);speed=vehicle.speed;if(snapCamera)snapChase(heading,p.y);followChase(heading,p,Math.min(dt,.1))}else{if(keys.q&&!vehicle.previousQ){vehicle.indicator=vehicle.indicator==='left'?null:'left';vehicle.indicatorTurned=false;}if(keys.e&&!vehicle.previousE){vehicle.indicator=vehicle.indicator==='right'?null:'right';vehicle.indicatorTurned=false;}if(keys.c)vehicle.indicator=null;vehicle.previousQ=!!keys.q;vehicle.previousE=!!keys.e;if(vehicle.indicator&&Math.abs(vehicle.steeringAngle||0)>.12)vehicle.indicatorTurned=true;if(vehicle.indicatorTurned&&Math.abs(vehicle.steeringAngle||0)<.035){vehicle.indicator=null;vehicle.indicatorTurned=false}accumulator+=Math.min(dt,.1);const step=1/120;if(snapCamera)snapChase(vehicle.yaw,vehicle.position.y);while(accumulator>=step){lastPhysics.position.set(vehicle.position.x,vehicle.position.y,vehicle.position.z);lastPhysics.yaw=vehicle.yaw;stepCar(vehicle,keys,step,world);followChase(vehicle.yaw,vehicle.position,step);accumulator-=step}alpha=accumulator/step;vehicle.renderPosition??=new T.Vector3();vehicle.renderPosition.copy(lastPhysics.position).lerp(new T.Vector3(vehicle.position.x,vehicle.position.y,vehicle.position.z),alpha);vehicle.renderYaw=T.MathUtils.lerp(lastPhysics.yaw,vehicle.yaw,alpha);p=vehicle.renderPosition;heading=vehicle.renderYaw;speed=Math.abs(vehicle.velocity)}const distance=chaseDistance(),height=chaseHeight(),viewYaw=T.MathUtils.lerp(lastChase.yaw,chase.yaw,alpha),viewY=T.MathUtils.lerp(lastChase.y,chase.y,alpha)+height+T.MathUtils.lerp(lastChase.lift,chase.lift,alpha),target=new T.Vector3(p.x+Math.sin(viewYaw)*distance,viewY,p.z+Math.cos(viewYaw)*distance),orientation=new T.Quaternion().setFromEuler(new T.Euler(-Math.atan2(viewY-p.y-height+distance*Math.tan(.22),distance),viewYaw,0,'YXZ'));if(firstPerson&&!vehicle.path){const m=vehicle.model||{},commercial=m.bus||m.van,floor=m.bus?.76:m.van?.53:m.ute?.55:.32,seatZ=commercial?-(m.length||4.5)/2+1.03:m.ute?(m.cabin[1]+m.cabin[2])/2-.08:(m.cabin?.[1]||-.57)+.53,eyeY=Math.min((m.roof||1.43)-.13,floor+(m.bus?.42:.22)+.69),body=new T.Quaternion().setFromEuler(new T.Euler(vehicle.inWater?vehicle.waterPitch||0:vehicle.bodyPitch||0,heading,vehicle.inWater?vehicle.waterRoll||0:vehicle.bodyRoll||0,'YXZ')),eye=new T.Vector3((m.width||1.8)*(m.bus?.31:.225),eyeY,seatZ+.03).applyQuaternion(body);camera.position.copy(p).add(eye);camera.quaternion.copy(body).multiply(new T.Quaternion().setFromEuler(new T.Euler(lookPitch,lookYaw,0,'YXZ')));camera.near=.035;camera.fov=74;vehicle.cockpitView=true}else{camera.position.copy(target);camera.quaternion.copy(orientation);camera.near=originalNear;camera.fov=originalFov;vehicle.cockpitView=false}camera.updateProjectionMatrix();snapCamera=false;status.textContent=`${!vehicle.path&&vehicle.inWater?vehicle.waterState+' · F SWIM / EXIT · R RECOVER · ':''}${vehicle.path?'TRAIN':'DRIVING · '+(vehicle.model?.name||'CAR')} · ${Math.round(speed*3.6)} KM/H · W/S ${vehicle.path?'POWER':'DRIVE'} · ${vehicle.path?'A/D DIRECTION':'A/D STEER'} · SPACE BRAKE · F EXIT`;return true}
 return{enter,exit,recover,relocate,toggleView,look,update,get firstPerson(){return !!vehicle?.cockpitView},get soundState(){return vehicle?{kind:vehicle.path?'train':'car',speed:Math.abs(vehicle.path?vehicle.speed:vehicle.velocity),bus:!!vehicle.model?.bus,rpm:vehicle.rpm,cylinders:vehicle.model?.id==='commodore'||vehicle.model?.id==='falcon'||vehicle.model?.id==='skyline'||vehicle.model?.bus?6:4,flooded:!!vehicle.engineFlooded,inWater:!!vehicle.inWater}:null},get active(){return !!vehicle}};
}
